-- 기록 저장소 고정 파일: 계약 1.17.0 · 엔진 0.4.1(커밋 98f34a1) 코드로 만든 저장소(합성 지도 표본 요청).
-- 판 호환 검사(tests/checks/records_compat.py)가 새 코드로 열어 본다. 다시 만들지 않는다(옛 판 증거).
-- 감사 줄 23개 · 기록 9개 · 사슬 머리 66c7fc7d26ad15e47a9db5aab1deb66e411ed8a6fef372a346ce3f2abb260519
BEGIN TRANSACTION;
CREATE TABLE audit (
    seq INTEGER PRIMARY KEY,
    ecn_id TEXT NOT NULL,
    entry TEXT NOT NULL,
    prev TEXT NOT NULL,
    digest TEXT NOT NULL
);
CREATE TABLE ecns (ecn_id TEXT PRIMARY KEY, status TEXT NOT NULL);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE records (
    record_id TEXT PRIMARY KEY,
    body TEXT NOT NULL,
    data_mode TEXT NOT NULL,
    snapshot_id TEXT NOT NULL
);
CREATE TABLE requests (
    request_id TEXT PRIMARY KEY,
    ecn_id TEXT NOT NULL,
    analysis_id TEXT NOT NULL,
    response TEXT NOT NULL
);
CREATE TABLE revisions (
    ecn_id TEXT NOT NULL,
    revision INTEGER NOT NULL,
    record_id TEXT NOT NULL REFERENCES records(record_id),
    recorded_at TEXT NOT NULL,
    actor TEXT NOT NULL,
    summary TEXT NOT NULL,
    PRIMARY KEY (ecn_id, revision)
);
CREATE INDEX audit_by_ecn ON audit(ecn_id, seq);
COMMIT;
PRAGMA user_version = 1;
